install.content:
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$version = '{{MINECRAFT_VERSION}}'
$manifest = Invoke-RestMethod -Uri 'https://piston-meta.mojang.com/mc/game/version_manifest.json'
if ($version -eq 'latest') { $version = $manifest.latest.release }
$entry = $manifest.versions | Where-Object { $_.id -eq $version }
if (-not $entry) { throw "Version Minecraft inconnue : $version" }
$meta = Invoke-RestMethod -Uri $entry.url
Invoke-WebRequest -Uri $meta.downloads.server.url -OutFile 'server.jar'
